groups = [(3,2),(8,3),(2,1),(8,2),(3,1),(7,2),(5,1),(8,2)]
n = 2*sum(h for c,h in groups)-2
g = [[0]*n for _ in range(n)]
inset = 0
for c,h in groups:
    end = n-inset
    for r in range(inset,end):
        for col in range(inset,end):
            if r < inset+h or r >= end-h or col < inset+h or col >= end-h:
                g[r][col] = c
    inset += h
print(n)
for row in g:
    print(' '.join(map(str,row)))
